import java.util.*;

class Solution {
    public int minDistanceExcludingMaxEdge(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[][] dist = new int[n][2];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, 0, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1], used = top[2];
            if (d > dist[u][used]) continue;
            if (u == n - 1 && used == 1) return d;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (d + w < dist[v][used]) {
                    dist[v][used] = d + w;
                    pq.offer(new int[]{d + w, v, used});
                }
                if (used == 0 && d < dist[v][1]) {
                    dist[v][1] = d;
                    pq.offer(new int[]{d, v, 1});
                }
            }
        }
        return Math.min(dist[n - 1][0], dist[n - 1][1]);
    }
}

